// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAccounts 账号列表（运维信息）
	// (GET /api/v1/admin/accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request, params ListAccountsParams)
	// ListPendingTerminals 等待批准的新终端
	// (GET /api/v1/admin/terminals/pending)
	ListPendingTerminals(w http.ResponseWriter, r *http.Request, params ListPendingTerminalsParams)
	// ApproveTerminal 批准新终端（它成为一个匿名账号的终端；每台的月上限在第 20 段加）
	// (POST /api/v1/admin/terminals/pending/{terminalId}/approve)
	ApproveTerminal(w http.ResponseWriter, r *http.Request, terminalId TerminalId)
	// RejectTerminal 拒绝新终端
	// (POST /api/v1/admin/terminals/pending/{terminalId}/reject)
	RejectTerminal(w http.ResponseWriter, r *http.Request, terminalId TerminalId)
	// Logout 登出（作废刷新令牌）
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// RefreshTokens 用刷新令牌换新的一对（刷新令牌用一次就作废）
	// (POST /api/v1/auth/refresh)
	RefreshTokens(w http.ResponseWriter, r *http.Request)
	// ListPhoneAlerts 从现在到 until 要在手机上响的提醒（App 排本地通知用；时间先后）
	// (GET /api/v1/calendar/alerts)
	ListPhoneAlerts(w http.ResponseWriter, r *http.Request, params ListPhoneAlertsParams)
	// CreateEvent 新建一条 haro 自己的日程
	// (POST /api/v1/calendar/events)
	CreateEvent(w http.ResponseWriter, r *http.Request)
	// DeleteEvent 删一条 haro 自己的日程（重复的用 scope 说删哪些）
	// (DELETE /api/v1/calendar/events/{eventId})
	DeleteEvent(w http.ResponseWriter, r *http.Request, eventId string, params DeleteEventParams)
	// GetEvent 一条日程
	// (GET /api/v1/calendar/events/{eventId})
	GetEvent(w http.ResponseWriter, r *http.Request, eventId string)
	// UpdateEvent 改一条 haro 自己的日程（重复的用 scope 说改哪些；返回改后的那条 —— 只改这一次、以后都改时是新拆出来的那条）
	// (PATCH /api/v1/calendar/events/{eventId})
	UpdateEvent(w http.ResponseWriter, r *http.Request, eventId string, params UpdateEventParams)
	// ListOccurrences 一段时间里的每一次（重复的已经展开；haro 自己的和系统日历同步进来的，开始的先后）
	// (GET /api/v1/calendar/occurrences)
	ListOccurrences(w http.ResponseWriter, r *http.Request, params ListOccurrencesParams)
	// ListCalendarSyncs 同步过的系统日历（上次同步的时间）
	// (GET /api/v1/calendar/syncs)
	ListCalendarSyncs(w http.ResponseWriter, r *http.Request)
	// SyncCalendar 交来一个系统日历在同步范围内的全部日程（重复的展开成每一次）；原来有、这次没交来的删掉
	// (PUT /api/v1/calendar/syncs/{calendarId})
	SyncCalendar(w http.ResponseWriter, r *http.Request, calendarId string)
	// GetClientConfig App 要用的业务参数（不用登录）
	// (GET /api/v1/client-config)
	GetClientConfig(w http.ResponseWriter, r *http.Request, params GetClientConfigParams)
	// ListConversations 对话列表（语音那条在最前，其余新的在前；不含删了的）
	// (GET /api/v1/conversations)
	ListConversations(w http.ResponseWriter, r *http.Request, params ListConversationsParams)
	// CreateConversation 新建一条对话
	// (POST /api/v1/conversations)
	CreateConversation(w http.ResponseWriter, r *http.Request)
	// DeleteConversation 删除（软删除，能恢复；语音那条不能删）
	// (DELETE /api/v1/conversations/{conversationId})
	DeleteConversation(w http.ResponseWriter, r *http.Request, conversationId ConversationId)
	// RestoreConversation 恢复删了的对话
	// (POST /api/v1/conversations/{conversationId}/restore)
	RestoreConversation(w http.ResponseWriter, r *http.Request, conversationId ConversationId)
	// ListTurns 往前翻这条对话（一页 page_size 轮，旧的在前）
	// (GET /api/v1/conversations/{conversationId}/turns)
	ListTurns(w http.ResponseWriter, r *http.Request, conversationId ConversationId, params ListTurnsParams)
	// StopTurn 停止正在答的这一轮（已经说出来的留着）
	// (POST /api/v1/conversations/{conversationId}/turns/{turnId}/stop)
	StopTurn(w http.ResponseWriter, r *http.Request, conversationId ConversationId, turnId string)
	// ListCountries 可选的国家（支持节假日的那些；名字按 Accept-Language）
	// (GET /api/v1/countries)
	ListCountries(w http.ResponseWriter, r *http.Request, params ListCountriesParams)
	// ListExpenseCategories 能选的分类：固定的几类在前（名字按语言），主人加的在后
	// (GET /api/v1/expense-categories)
	ListExpenseCategories(w http.ResponseWriter, r *http.Request)
	// AddExpenseCategory 加一个自己的分类
	// (POST /api/v1/expense-categories)
	AddExpenseCategory(w http.ResponseWriter, r *http.Request)
	// DeleteExpenseCategory 删一个自己加的分类（固定的几类删不了：404）；用过它的账目留着，分类显示成「已删的分类」
	// (DELETE /api/v1/expense-categories/{categoryKey})
	DeleteExpenseCategory(w http.ResponseWriter, r *http.Request, categoryKey string)
	// ListExpenses 一个月的账目（新的在前）；可以只看一个分类或一家店
	// (GET /api/v1/expenses)
	ListExpenses(w http.ResponseWriter, r *http.Request, params ListExpensesParams)
	// CreateExpense 手记一笔（没有小票）
	// (POST /api/v1/expenses)
	CreateExpense(w http.ResponseWriter, r *http.Request)
	// SummarizeExpenses 一个月的汇总：合计（换成默认货币 + 按币种分开 + 换算提示）、按分类、按店（各自按合计从大到小）、上个月的合计
	// (GET /api/v1/expenses/summary)
	SummarizeExpenses(w http.ResponseWriter, r *http.Request, params SummarizeExpensesParams)
	// DeleteExpense 删一笔账，原图跟着删
	// (DELETE /api/v1/expenses/{expenseId})
	DeleteExpense(w http.ResponseWriter, r *http.Request, expenseId ExpenseId)
	// GetExpense 一笔账（明细行；有原图时 has_image 为 true）
	// (GET /api/v1/expenses/{expenseId})
	GetExpense(w http.ResponseWriter, r *http.Request, expenseId ExpenseId)
	// UpdateExpense 改一笔账（整笔替换；原图不变）
	// (PUT /api/v1/expenses/{expenseId})
	UpdateExpense(w http.ResponseWriter, r *http.Request, expenseId ExpenseId)
	// GetMe 登录的这个账号
	// (GET /api/v1/me)
	GetMe(w http.ResponseWriter, r *http.Request, params GetMeParams)
	// UpdateMe 改显示名、默认货币
	// (PATCH /api/v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// GetHome 家的位置（天气用）和节假日的国家
	// (GET /api/v1/me/home)
	GetHome(w http.ResponseWriter, r *http.Request, params GetHomeParams)
	// ReplaceHome 改家的位置、节假日的国家
	// (PUT /api/v1/me/home)
	ReplaceHome(w http.ResponseWriter, r *http.Request)
	// GetOverview 「我的」页的摘要（一个接口给齐）
	// (GET /api/v1/me/overview)
	GetOverview(w http.ResponseWriter, r *http.Request, params GetOverviewParams)
	// GetProfile 主人资料（每次对话都会带给 haro）
	// (GET /api/v1/me/profile)
	GetProfile(w http.ResponseWriter, r *http.Request)
	// ReplaceProfile 整份替换主人资料
	// (PUT /api/v1/me/profile)
	ReplaceProfile(w http.ResponseWriter, r *http.Request)
	// GetBackstory 背景记录池（后台从对话整理的「关于主人的背景」，每轮带给 haro）
	// (GET /api/v1/memory/backstory)
	GetBackstory(w http.ResponseWriter, r *http.Request)
	// UpdateBackstory 开、关背景记录池（关了就不带、也不更新）
	// (PATCH /api/v1/memory/backstory)
	UpdateBackstory(w http.ResponseWriter, r *http.Request)
	// DeleteBackstoryItem 删一条
	// (DELETE /api/v1/memory/backstory/items/{itemId})
	DeleteBackstoryItem(w http.ResponseWriter, r *http.Request, itemId string)
	// EditBackstoryItem 改一条（改过的以主人为准，后台整理时不再改、不删）
	// (PATCH /api/v1/memory/backstory/items/{itemId})
	EditBackstoryItem(w http.ResponseWriter, r *http.Request, itemId string)
	// ListNotes 记过的事（常驻的、一般的；新的在前）和最近忘掉的（找回用）
	// (GET /api/v1/memory/notes)
	ListNotes(w http.ResponseWriter, r *http.Request)
	// ForgetNote 忘掉一条（能找回）
	// (DELETE /api/v1/memory/notes/{noteId})
	ForgetNote(w http.ResponseWriter, r *http.Request, noteId NoteId)
	// RestoreNote 找回忘掉的一条
	// (POST /api/v1/memory/notes/{noteId}/restore)
	RestoreNote(w http.ResponseWriter, r *http.Request, noteId NoteId)
	// SearchPlaces 搜地名（只到区 / 市，设家的位置用）
	// (GET /api/v1/places)
	SearchPlaces(w http.ResponseWriter, r *http.Request, params SearchPlacesParams)
	// DiscardReceipt 不要这张小票了（不入账，或者解析失败了要重拍）：连原图一起删。还在解析、已经入账的不行（409）
	// (DELETE /api/v1/receipts/{receiptId})
	DiscardReceipt(w http.ResponseWriter, r *http.Request, receiptId ReceiptId)
	// GetReceipt 一张小票的状态和草稿（解析中的隔几秒再取）
	// (GET /api/v1/receipts/{receiptId})
	GetReceipt(w http.ResponseWriter, r *http.Request, receiptId ReceiptId)
	// ConfirmReceipt 交回（可能改过的）草稿，入账；原图跟着这笔账。只有解析好了的（status = ready）能确认，别的回 409
	// (POST /api/v1/receipts/{receiptId}/confirm)
	ConfirmReceipt(w http.ResponseWriter, r *http.Request, receiptId ReceiptId)
	// ListResearchTasks 后台调查（新的在前）
	// (GET /api/v1/research/tasks)
	ListResearchTasks(w http.ResponseWriter, r *http.Request, params ListResearchTasksParams)
	// GetResearchTask 一个调查：结论（Markdown）和来源
	// (GET /api/v1/research/tasks/{taskId})
	GetResearchTask(w http.ResponseWriter, r *http.Request, taskId int64, params GetResearchTaskParams)
	// GetSpending 这个月和今天的花费（默认货币，带换算提示）
	// (GET /api/v1/spending)
	GetSpending(w http.ResponseWriter, r *http.Request, params GetSpendingParams)
	// ListTerminals 这个账号的终端
	// (GET /api/v1/terminals)
	ListTerminals(w http.ResponseWriter, r *http.Request, params ListTerminalsParams)
	// PairTerminal 用终端给的配对码把它绑到这个账号
	// (POST /api/v1/terminals/pair)
	PairTerminal(w http.ResponseWriter, r *http.Request)
	// RemoveTerminal 移除终端（它的凭证立即作废）
	// (DELETE /api/v1/terminals/{terminalId})
	RemoveTerminal(w http.ResponseWriter, r *http.Request, terminalId TerminalId)
	// RenameTerminal 改终端的名字
	// (PATCH /api/v1/terminals/{terminalId})
	RenameTerminal(w http.ResponseWriter, r *http.Request, terminalId TerminalId)
	// SearchTurns 搜以前的对话（按文字和按意思找到的合在一起，新的在前；删了的对话里的不算）
	// (GET /api/v1/turns/search)
	SearchTurns(w http.ResponseWriter, r *http.Request, params SearchTurnsParams)
}

